//! hbot-rpc：UI 协议与应用层入口。
//!
//! 职责（`docs/03-directory.md` §2）：`Command` / `Event` DTO、dispatch、WS 服务；
//! 只做参数校验、编排与错误映射，业务规则不下沉。
//!
//! 契约唯一真源是 [`dto`]；面向 UI 的 TypeScript 由 [`ts`] 生成到
//! `apps/web/src/generated/`（`cargo xtask gen`，生成文件头写
//! `// @generated by xtask; do not edit`）。生成物入库，review 但不要手改。
//!
//! [`dispatch`]（唯一入口）与 [`ws`]（后台模式：auth、限流、背压）已就位，
//! 见 `docs/02-architecture.md` §9 与 `docs/03-directory.md` §2.2。

#![warn(missing_docs)]

pub mod app;
pub mod dispatch;
pub mod dto;
pub mod ts;
pub mod ws;

pub use app::{AppState, EventBus};
pub use dispatch::Dispatcher;
pub use dto::{
    ApiError, AppInfo, Command, DebugScope, Diagnostic, DiagnosticSeverity, DiffHunk, DirEntry,
    EditFile, Event, FileChangeKind, FileContent, LogLevel, Response, RiskLevel, RunLog,
    SearchMatch, StackFrame, StepKind,
};
pub use ws::{WsConfig, WsHandle, WsMetrics, WsServer, serve};
